1.4.5 step 5 引入大语言模型
要提供三个信息：API_KEY、BASE_URL 和 MODEL_ID，具体值取决于您使用的服务商（如 OpenAI 官方、Azure、或 Ollama 等本地模型）


Code
library(httr)
library(jsonlite)

OpenAICompatibleClient &lt;- function(model, api_key = "ollama", base_url) {

  client &lt;- list(
    model = model,
    api_key = api_key,
    base_url = base_url
  )

  client$generate &lt;- function(prompt, system_prompt) {

  message("正在调用大语言模型...")

  body &lt;- list(
    model = client$model,
    messages = list(
      list(role = "system", content = system_prompt),
      list(role = "user",   content = prompt)
    ),
    stream = FALSE
  )

  res &lt;- tryCatch({
    POST(
      url = paste0(client$base_url, "/v1/chat/completions"),
      add_headers(
        Authorization = paste("Bearer", client$api_key),
        `Content-Type` = "application/json"
      ),
      body = toJSON(body, auto_unbox = TRUE),
      encode = "raw",
      timeout(120)
    )
  }, error = function(e) {
    message("调用 LLM API 时发生错误: ", e$message)
    return(NULL)
  })

  if (is.null(res) || status_code(res) != 200) {
    return("错误: 调用语言模型服务时出错。")
  }

  # 🔴 关键：关闭简化
  data &lt;- fromJSON(
    content(res, "text", encoding = "UTF-8"),
    simplifyVector = FALSE
  )

  answer &lt;- tryCatch({

    # Ollama / OpenAI 兼容
    if (!is.null(data$choices[[1]]$message$content)) {
      data$choices[[1]]$message$content
    } else if (!is.null(data$choices[[1]]$text)) {
      data$choices[[1]]$text
    } else {
      stop("未找到模型输出字段")
    }

  }, error = function(e) {
    paste("错误: 无法解析模型返回结果 -", e$message)
  })

  message("大语言模型响应成功。")
  answer
}

  class(client) &lt;- "OpenAICompatibleClient"
  client
}


llm &lt;- OpenAICompatibleClient(
  model    = "gemma3:12b",
  base_url = "http://localhost:11434"
)


resutl &lt;- llm$generate(
