1.4.6 step 5 构建智能体
智能体必须展现出清晰的逻辑规划能力。它需要先调用天气查询工具，并将获得的观察结果作为下一步的依据。在下一轮循环中，它再调用景点推荐工具，从而得出最终建议。


Code
# 抓去action 
extract_last_action &lt;- function(text) {
  actions &lt;- str_match_all(text, "Action:\\s*(.*)")[[1]]
  if (nrow(actions) == 0) return(NA)
  str_trim(tail(actions[, 2], 1))
}

is_finish &lt;- function(action_str) {

  str_starts(action_str, "Finish")
}
normalize_action &lt;- function(action_str) {
  action_str |&gt;
    str_trim() |&gt;                # 去首尾空白
    str_remove("^`+") |&gt;         # 去前面的 `
    str_remove("`+$")            # 去后面的 `
}

extract_finish &lt;- function(action_str) {
  str_match(action_str, "Finish\\[(.*)\\]")[1, 2]
}


