user_prompt &lt;- "你好，请帮我查询一下今天北京的天气，然后根据天气推荐一个合适的旅游景点。"
prompt_history &lt;- c(paste0("用户请求: ", user_prompt))

cat("用户输入: ", user_prompt, "\n")
cat(strrep("=", 40), "\n")

# --- 3. 运行主循环 ---
for (i in seq_len(5)) {

  cat(paste0("\n--- 循环 ", i, " ---\n\n"))

  # 3.1 构建 Prompt
  full_prompt &lt;- paste(prompt_history, collapse = "\n")

  # 3.2 调用 LLM
  llm_output &lt;- llm$generate(
    prompt = full_prompt,
    system_prompt = AGENT_SYSTEM_PROMPT
  )
  res = strip_think(llm_output)


  cat("模型输出:\n")
  cat(res, "\n\n")


  prompt_history &lt;- c(prompt_history, res)

  # 3.3 解析 Action
  action_str &lt;- extract_last_action(res)
  action_str &lt;- normalize_action(action_str)
   if (is_finish(action_str)) {
  final_answer &lt;- extract_finish(action_str)
  writeLines(final_answer)
  break
}

  if (is.na(action_str)) {
  observation_str &lt;- "Observation: 错误: 未能解析到 Action。"
  prompt_history &lt;- c(prompt_history, observation_str)
  next
}




  # --- 解析工具名与参数 ---
  tool_name &lt;- str_match(action_str, "(\\w+)\\(")[1, 2]
  args_str  &lt;- str_match(action_str, "\\((.*)\\)")[1, 2]

  kwargs &lt;- list()
  arg_matches &lt;- str_match_all(args_str, '(\\w+)="([^"]*)"')[[1]]
  if (nrow(arg_matches) &gt; 0) {
    for (j in seq_len(nrow(arg_matches))) {
      kwargs[[arg_matches[j, 2]]] &lt;- arg_matches[j, 3]
    }
  }

  # --- 执行工具 ---
  if (tool_name %in% names(available_tools)) {
    fn &lt;- available_tools[[tool_name]]$fn
    observation &lt;- tryCatch(
      do.call(fn, kwargs),
      error = function(e) paste("工具执行错误:", e$message)
    )
  } else {
    observation &lt;- paste0("错误: 未定义的工具 '", tool_name, "'")
  }

  # 3.4 记录 Observation
  observation_str &lt;- paste0("Observation: ", observation)
  cat(observation_str, "\n", strrep("=", 40), "\n")
  prompt_history &lt;- c(prompt_history, observation_str)
}


这个简单的旅行助手案例，集中演示了基于Thought-Action-Observation范式的智能体所具备的四项基本能力：任务分解、工具调用、上下文理解和结果合成。正是通过这个循环的不断迭代，智能体才得以将一个模糊的用户意图，转化为一系列具体、可执行的步骤，并最终达成目标。

6.15 工具系统

6.15.1 基础工具类
# HelloAgents/tools/base.py
from __future__ import annotations

from abc import ABC, abstractmethod
from dataclasses import dataclass
from typing import Any, Dict, List


@dataclass
class ToolParameter:
    name: str
    type: str  # "string" | "number" | "boolean" | "object" | "array"
    description: str
    required: bool = True
    default: Any = None


class Tool(ABC):
    """所有工具的统一接口：run(parameters) -&gt; str"""

    def __init__(self, name: str, description: str):
        self.name = name
        self.description = description

    @abstractmethod
    def run(self, parameters: Dict[str, Any]) -&gt; str:
        raise NotImplementedError

    @abstractmethod
    def get_parameters(self) -&gt; List[ToolParameter]:
        raise NotImplementedError


6.15.2 工具注册
# HelloAgents/tools/registry.py
from __future__ import annotations

import json
from typing import Any, Callable, Dict, Optional

from HelloAgents.tools.base import Tool


class ToolRegistry:
    """
    统一的工具注册表。
    - register_tool(Tool): 复杂工具（结构化参数）
    - register_function(name, description, func): 简单工具（str -&gt; str）
    - execute_tool(name, raw_params): 统一执行入口
    """

    def __init__(self):
        self._tools: Dict[str, Tool] = {}
        self._functions: Dict[str, Dict[str, Any]] = {}

    def register_tool(self, tool: Tool) -&gt; None:
        if tool.name in self._tools or tool.name in self._functions:
            print(f"⚠️ 警告:工具 '{tool.name}' 已存在，将被覆盖。")
        self._tools[tool.name] = tool
        print(f"✅ 工具 '{tool.name}' 已注册(Tool)。")

    def register_function(self, name: str, description: str, func: Callable[[str], str]) -&gt; None:
        if name in self._tools or name in self._functions:
            print(f"⚠️ 警告:工具 '{name}' 已存在，将被覆盖。")
        self._functions[name] = {"description": description, "func": func}
        print(f"✅ 工具 '{name}' 已注册(Function)。")

    def get_tool(self, name: str) -&gt; Optional[Tool]:
        return self._tools.get(name)

    def list_tools(self) -&gt; list[str]:
        return sorted(set(list(self._tools.keys()) + list(self._functions.keys())))

    def get_tools_description(self) -&gt; str:
        lines = []
        for t in self._tools.values():
            lines.append(f"- {t.name}: {t.description}")
        for name, info in self._functions.items():
            lines.append(f"- {name}: {info['description']}")
        return "\n".join(lines) if lines else "暂无可用工具"

    def execute_tool(self, name: str, raw_params: str) -&gt; str:
        """
        raw_params 兼容两种形态：
        1) JSON 字符串：{"expression": "2+2"} / {"text":"...","pattern":"..."}
        2) 普通字符串：直接作为 input
        """
        if name in self._tools:
            tool = self._tools[name]
            params = self._parse_raw_params(raw_params)
            return tool.run(params)

        if name in self._functions:
            func = self._functions[name]["func"]
            # function 工具就吃纯字符串
            return str(func(raw_params))

        raise KeyError(f"未找到工具: {name}")

    def _parse_raw_params(self, raw: str) -&gt; Dict[str, Any]:
        raw = (raw or "").strip()
        if not raw:
            return {"input": ""}

        # 优先尝试 JSON
        if (raw.startswith("{") and raw.endswith("}")) or (raw.startswith("[") and raw.endswith("]")):
            try:
                obj = json.loads(raw)
                if isinstance(obj, dict):
                    return obj
                # 如果是 list，就包一层
                return {"input": obj}
            except Exception:
                # 解析失败就当普通字符串
                return {"input": raw}

        return {"input": raw}


6.15.3 定义工具

6.15.3.1 计算器
# HelloAgents/tools/builtin/calculator.py
from __future__ import annotations

import ast
import math
import operator
from typing import Any, Dict, List

from HelloAgents.tools.base import Tool, ToolParameter


class CalculatorTool(Tool):
    """
    安全计算器：
    - 支持 + - * / ** ( ) 以及常量 pi, e
    - 支持函数: sqrt, sin, cos, tan, log
    输入参数支持：
    - {"expression": "..."}
    - {"input": "..."}  # 兼容 ToolRegistry 的字符串模式
    """

    def __init__(self):
        super().__init__(name="calculator", description="安全数学计算工具，输入 expression 返回计算结果。")

    def get_parameters(self) -&gt; List[ToolParameter]:
        return [
            ToolParameter(name="expression", type="string", description="数学表达式，如 '2 + 3 * 4'。", required=False),
            ToolParameter(name="input", type="string", description="表达式的别名输入(兼容模式)。", required=False),
        ]

    def run(self, parameters: Dict[str, Any]) -&gt; str:
        expr = (parameters.get("expression") or parameters.get("input") or "").strip()
        if not expr:
            return "错误：expression 不能为空"

        try:
            value = self._safe_eval(expr)
            # 统一字符串输出，便于模型消费
            return str(value)
        except Exception as e:
            return f"计算失败：{e}"

    def _safe_eval(self, expr: str) -&gt; Any:
        allowed_binops = {
            ast.Add: operator.add,
            ast.Sub: operator.sub,
            ast.Mult: operator.mul,
            ast.Div: operator.truediv,
            ast.Pow: operator.pow,
            ast.Mod: operator.mod,
        }
        allowed_unary = {
            ast.UAdd: operator.pos,
            ast.USub: operator.neg,
        }
        allowed_names = {
            "pi": math.pi,
            "e": math.e,
        }
        allowed_funcs = {
            "sqrt": math.sqrt,
            "sin": math.sin,
            "cos": math.cos,
            "tan": math.tan,
            "log": math.log,
        }

        node = ast.parse(expr, mode="eval")

        def _eval(n):
            if isinstance(n, ast.Expression):
                return _eval(n.body)
            if isinstance(n, ast.Constant):  # py3.8+
                if isinstance(n.value, (int, float)):
                    return n.value
                raise ValueError("不支持的常量类型")
            if isinstance(n, ast.BinOp):
                op = allowed_binops.get(type(n.op))
                if not op:
                    raise ValueError("不支持的二元运算")
                return op(_eval(n.left), _eval(n.right))
            if isinstance(n, ast.UnaryOp):
                op = allowed_unary.get(type(n.op))
                if not op:
                    raise ValueError("不支持的一元运算")
                return op(_eval(n.operand))
            if isinstance(n, ast.Name):
                if n.id in allowed_names:
                    return allowed_names[n.id]
                raise ValueError(f"不支持的变量: {n.id}")
            if isinstance(n, ast.Call):
                if not isinstance(n.func, ast.Name):
                    raise ValueError("不支持的函数调用形式")
                fname = n.func.id
                if fname not in allowed_funcs:
                    raise ValueError(f"不支持的函数: {fname}")
                args = [_eval(a) for a in n.args]
                return allowed_funcs[fname](*args)

            raise ValueError("不支持的表达式结构")

        return _eval(node)



6.15.3.2 获取时间
# HelloAgents/tools/builtin/datetime_tool.py
from __future__ import annotations

from datetime import datetime, timezone
from typing import Any, Dict, List

from HelloAgents.tools.base import Tool, ToolParameter


class DateTimeTool(Tool):
    """
    返回当前时间（UTC 或本地）
    输入：
    - {"tz": "utc"} / {"tz": "local"}
    - {"format": "%Y-%m-%d %H:%M:%S"}
    """

    def __init__(self):
        super().__init__(name="now", description="获取当前时间。支持 tz=utc/local 与 format 自定义格式。")

    def get_parameters(self) -&gt; List[ToolParameter]:
        return [
            ToolParameter(name="tz", type="string", description="时区: utc 或 local", required=False, default="local"),
            ToolParameter(name="format", type="string", description="时间格式化字符串", required=False, default="%Y-%m-%d %H:%M:%S"),
        ]

    def run(self, parameters: Dict[str, Any]) -&gt; str:
        tz = (parameters.get("tz") or "local").strip().lower()
        fmt = parameters.get("format") or "%Y-%m-%d %H:%M:%S"

        if tz == "utc":
            dt = datetime.now(timezone.utc)
        else:
            dt = datetime.now()

        try:
            return dt.strftime(fmt)
        except Exception as e:
            return f"时间格式化失败：{e}"




